func:
// 送信先は http request ノード側に POST を設定してある。
// オブジェクトを渡せば JSON で送られる。

// exec ノードは3本の出力（stdout / stderr / rc）が別々に届く。
// rc が来たときだけ判定し、それ以外は出力を貯めておく。
if (!(typeof msg.payload === 'object' && msg.payload && 'code' in msg.payload)) {
    flow.set('pcg_out', (flow.get('pcg_out') || '') + String(msg.payload || ''));
    return [null, null];
}

const code = msg.payload.code;
const out = flow.get('pcg_out') || '';
flow.set('pcg_out', '');

// スクリプトが最後に出す __STATUS__ 行を拾う（無くても動く）
let status = null;
const m = out.match(/__STATUS__ (\{.*\})/);
if (m) { try { status = JSON.parse(m[1]); } catch (e) { /* 無視 */ } }

flow.set('pcg_last', { code, at: new Date().toISOString(), status });
const stamp = new Date().toLocaleString('ja-JP');

if (code === 0) {
    // 更新が無い日のほうが多いので、静かにしておく
    if (!status || !status.updated) {
        node.status({ fill: 'grey', shape: 'ring', text: '更新なし ' + stamp });
        return [null, null];
    }
    node.status({ fill: 'green', shape: 'dot', text: '更新 ' + stamp });
    msg.payload = { content: `🏆 ポケカ 大会結果を更新しました（全 ${status.count} 件）` };
    return [msg, null];
}

const title = {
    30: '⚠️ ポケカ 大会結果: 取得できませんでした（ボット対策に当たった可能性）',
    40: '⚠️ ポケカ 大会結果: GitHub への反映に失敗しました',
}[code] || '❌ ポケカ 大会結果: 更新に失敗しました';

const reason = status && status.reason ? `\n理由: ${status.reason}` : '';
const tail = out.trim().split('\n').slice(-6).join('\n');

node.status({ fill: 'red', shape: 'dot', text: '失敗 ' + stamp });
msg.payload = { content: (title + reason + (tail ? '\n```\n' + tail + '\n```' : '')).slice(0, 1900) };
return [msg, { payload: { code, status, out: tail } }];
